INSERT INTO `appraisals` (`id`, `employee_id`, `appraiser_id`, `last_appraisal_id`, `appraiser_date`, `status`, `past_year_review`, `achievements`, `org_likes_dislikes`, `other_issues`, `employee_submit_date`, `appraiser_review_date`, `hr_review_date`, `hr_comment`, `ai_summary`, `created_at`, `updated_at`) VALUES (1,104,83,0,'2009-01-30','completed','Good as i learnt lot of new things about linux and remote administration.','To get placed and getting responsiblity of Network administrator // To pass Securing network devices exam of CCSP track.','Everything here is top of the world except some power issues and downtime of net.','Sometime really misses to have a mentor or senior who can teach me when i am stucked on a point in my administration.. ',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(2,103,82,0,'2009-04-01','completed','Â good because I worked on a new technology on different platform. Worked on a live project.','Approval of RCS project','Â Like: Friendly working environment , every body very co-operative, group picnics are  very refreshing......\r\nDislike: lack of books on cocoa in company library, lack of experienced person in cocoa due to which some times we take more time to resolve a simple problem!','Â It will be good for cocoa department if we will have one more mac.\r\nIt is always good to find Pramod sir and Madhulika ma\'m in office. \r\n',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(3,106,74,0,'2009-07-01','submitted_to_appraiser','Â Last year being good for me as it was my first industrial experience I have spent 6 months in a good company','I have learned to work in industrial environment under different conditions and under Presure. I consider it as most important thing for me that helpful for me in futureÂ  ','In the organization environment is good, whole staff is very helpful.Â ','In organization some sites are blocked That is good but some blocked sites like gmail should be open for some time say\r\n 30-45 mints 2 or 3 days in a week so that Employee can check their mails. Â ',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:17:18','2025-08-22 09:17:18'),
(4,105,77,0,'2009-07-01','completed','Good.\r\nAs it was my first experience in the IT industry I have learned a lot here, Both as technically and socially. ','1)I have learned the latest web developing language PHP.\r\n2) Worked on several projects like ntpnow.com ,Krooza.com,Status,Zencart(working) Status\r\nand learned a lot and done my honest efforts.   ','Working in this organization is quite Experiencing for me as it was my first step to the Software Development Field.\r\n2)Helpful and co cooperative staff. \r\n3)working environment is too good.\r\n','Â I think There will be more output,If the project is given to the team Instead of the Individual in Case of a Big Project. ',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(5,108,77,0,'2009-07-01','completed','It was Good for me, because i have learned a lot in this period of six month training. ','I had coded for auto installer in e-store, and coded for salary processing in and URL rewriting in Status Paykey.For that i had studied new things like javascript ,AJAX and php etc. which i think, is a good achievement for me. ','1.I like the working environment in this organization as everybody who is working here,pay full attention in their work.\r\n2.Everyone try to help each other in any working problem.','There should be proper group discussions on different issues at least on fortnightly basis. It will help everyone in organization to improve their self confidence,communication skills and participation.',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(6,107,82,0,'2009-07-01','completed','Â It was good for me because in this interval of my six month training, i have learnt a lot about COCOA. As i worked in this technology, my basics get more clear.\r\nI got the chance to work on mac.It was new for me to do the work on Mac OSx.',' As i have worked in all modules of RCS project, so i think it is a good achievement for me as a trainee to work in such a big project.','I like the team work in this organization especially in COCOA team. In this Organization everyone is ready to help each other any time regarding their working problems. There is familiar environment in the Organization.','There can be improvement in communication skills and self confidence of employees if certain kind of extra curicullar activities like group discussions are included.',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(7,77,82,0,'2009-08-01','completed','Past year has been satisfactory for me. I have  got opportunity to work with estoreadvanced package. Our company became an MNC. our compa got a plot for permanent office. On the other hand our company has less projects in hand.','Working with packages like oScommerce. Created a friendly environment with Team Members. ','What I like is our organization gives opportunity to work with wide range of platforms. If a 2 year experienced person wants to become Team leader it is possible only in our Organizaton. Also we enjoy parties and Tours very frequently. What I do not like is Our company developed india\'s first memorial website but did not marketed it.','No',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(8,99,82,0,'2010-02-01','completed','Good because I worked successfully on more than one live projects like,  http://clik-a-site.com,  http://ksc.co.in,   http://eroticconnexions.co.nz  ,  http://keysoftwareservices.com , http://www.motorville.com, http://estoreadvanced.com ,\r\n http://estoreadvanced.net , http://dictionsoftware.estoreadvanced.biz/ , http://keysoftwareservices.co.in \r\n','complete the div projects like  Coram,  \r\n groundzeroroofing.com complete with 13 pages, \r\n webrevelation ,  ozarka Water Company and html  Traveling on pennies projects\r\n','I like the cooperative behave of company ','no',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(9,74,83,0,'2010-03-01','completed','Very Good, Work on new platform (mac/cocoa)..Work on cocoa is a challenging job as we all(Cocoa Team) are freshers for mac/cocoa, but all are interesting. ','Apply internal updates in RCS and resolved the crash issue while internal updates... Successful implementation of Contact, messaging and alerts in RCS..','Like : We have a experience person for client interaction due to this our RCS project is successful project, Company environment of party on every little moment of happiness \r\n....................\r\nDislike : bad culture of working late night.... and no approach taken to avoid it.\r\n','For company growth need more & more project and more employees\r\n',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(12,103,82,2,'2010-04-01','submitted_to_appraiser','Past year has been good for me because we successfully moved forward with RCS. We also got wonderful opportunity of making specific modules on iPhone for RCS. ','1. My most important achievement of the past year was making and integrating chat application module in RCS. The whole concept was new to me and I did not know any of its basics but then also I did not give up and managed to implement it from very basic. \r\n2. Successful launch of RCS on cloud computing environment.\r\n3. Minimizing crashes occurring in RCS approximately to nil. ','Like:\r\n1.  Every one is very helpful and co-operative. If we have any doubt we can directly ask it from our seniors.\r\n2. In RCS we have developed a good habit of discussing before implementing any feature. It saves a lot of valuable time while coding.\r\n3. Shivadya sir is designer but still when we are caught in some coding problem, he leaves no stone unturned to help us by suggesting best of his logics and google links.\r\n4. When time frame is crossed and any work is incomplete due to some bugs o','Working on apple computers as a user and as a developer is a very rich experience. There is a lot of depth in them which is unexplored. The more we explore the more we gain and the more we will bring work and ultimately profit to our company. There are various features and applications which are still untouched such as - dashboard development widget, AppleScript, Automator. I think that employees should be motivated to learn and gain more knowledge by sharing links etc.  ',NULL,NULL,NULL,NULL,NULL,'2025-08-22 09:17:18','2025-08-22 09:17:18'),
(13,81,83,0,'2010-05-01','completed','Good, Because I worked on many live project and also\r\ngot more knowledge in oscommerce, estoreadvanced\r\n, word press etc.','To finished the new site for Mark on the oscommerce\r\nbased. On this site, I implement new design and javascript\r\ncoding and finished 100% complete.','I like very much this organisation because here\r\nI found good environment to develop my career \r\nand personality.','I will like if our organization provide us opportunity \nfor tour.',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(14,82,83,0,'2010-04-01','completed','Good becoz we could pull it off for RCS, Ginda Ji was happy overall... Satisfactory becoz  average no projects per month remained same from Tim... ','RCS UI and Managing RCS project... I think I improved my layout quality a level up overall...','I like the freedom of thought and expression both... Nothing to dislike as such...','Marketing needs a push...',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(15,100,82,0,'2010-03-01','completed','it was Good, because I worked on various projects for different clients, such as-\r\n1. Tims Projects \r\n2. mark projects',' i have done successfully  HTML projects  i have learned a lot  about HTML and  photo shop layout  worked on  e-storeAdvance ','i  Like cooperative behave of all members ','none',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(16,107,82,6,'2010-07-01','completed','It was good for me. I have learned  more things regarding Cocoa.','I have worked on various modules on RCS.\r\nI have worked on iRCS.','Like: Team Work, familier environment in office. I like to work under Shivadya Sir because he manages everything in a proper way & interacts with client. \r\nDislike :- Late night working, No official parties or tour.we do not get leave easily. ','None',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(17,108,77,5,'2010-07-01','completed','It was quite good for me as i have worked on many online projects and learned many new things.','I had got the opportunity to work on Linkshare, Ning Application,hahatoofunny.com and World Dance Shop customizations and SEO for it.','1. I like the familiar and helping environment here.\r\n2. I want to avoid late night working because we have faced problems many times due to it.','I think there should be proper interaction with employees at regular intervals which are quite less as compared to last year.',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(18,105,77,4,'2010-07-01','completed','Good because I learned much about PHP, javascript,CSS ,FBML,FBJS , worked on different projects and got good working environment. \r\n\r\n','Successfully developed facebook ememorial application and got the knowledge of\r\nFBML and FBJS.\r\nAlso learned to Integrate site with twitter and facebook.\r\n\r\n','Cooperative and friendly working environment. \r\n\r\nOpportunity  to work under dynamic responsibilities.\r\n\r\n','none',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(19,109,82,0,'2010-08-01','completed','Yes, last satisfactory for me. I worked on new technology and learned very much things.','I published more than 10 app on itune stores','Like\r\nvery friendly atmosphere to work on.  \r\nDislike\r\nNo extra curricular activities.\r\n','No weekend parties',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(20,77,82,7,'2010-08-01','completed','Previous year I worked in Sasha\'s project and default estore and small customizations of estore and ntpnow. I also worked for Joe\'s project. Overally some results were good some are not. So previous year was not so bad and not so good. Satisfactory.','Worked with new things like Printfection API, Flash & actionscript and Flex.','I like the office environment most. There is no office politics. I enjoy the parties too.\r\nWhat I don\'t like is Company does not hires senior developers.\r\n','No other issues',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(21,94,82,0,'2010-09-01','completed','Overall this year was  Good as we Got chance to work on good Projects though Inhouse but atleast from begining .Also some Projects of Wordpress and Pinacle cart.\r\n','It was Good this year as we Got chance to work on good Projects .Got the chance to work on Projects such as Keyss Estore,Ks,And Some of the Sites Of Pinacle Cart such as theglassandwindowcentre.co.uk,stoneessentialsonline.com,theemotionlink and a few Mark\'s Wordpress site ','Like-Its friendly envoirnment\r\nDislike- Less number of Paid PHP Projects.','No Issues',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(22,118,83,0,'2010-11-01','completed','Good i have learn a lot about the html  and design issue ','I have successfully worked on html','i like environment of the company','none',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
(23,99,82,8,'2011-03-01','completed','it was Good because I have learn a lot and work on some new technology like wordpress, Html5 and Css3. ','wordpress, Div, css3 and Photoshop skills  was the most important achievements of the past year','Likes\r\n\r\nnew machines in designers cabin. \r\ncooperative behavior of my colleagues.   \r\n\r\nDislikes\r\nin appropriate information for inhouse projects, which make project so longer.  ','No.',NULL,NULL,NULL,'',NULL,'2025-08-22 09:12:23','2025-08-22 09:12:23'),
